#!/usr/bin/env bash
# MacTranslator one-shot build using swiftc + Command Line Tools (no Xcode required).
# Output: build/MacTranslator.app
#
# Verified on macOS 15 / x86_64 / Command Line Tools (Swift 6.1.2).
# This machine has no Xcode, so `momc` and `actool` are unavailable:
#   - The Core Data .momd is generated by an embedded Swift helper that parses
#     Model.xcdatamodel/contents into the same keyed archive momc would emit.
#   - Assets.xcassets only contains Contents.json and the code uses system
#     images (NSImage.statusAvailableName), so no Assets.car is needed.

set -euo pipefail

APP_NAME="MacTranslator"
BUNDLE_ID="com.mactranslator.app"
ROOT="$(cd "$(dirname "$0")" && pwd)"
SRC="$ROOT/Sources/MacTranslator"
BUILD="$ROOT/build"
APP="$BUILD/$APP_NAME.app"
CONTENTS="$APP/Contents"
MACOS="$CONTENTS/MacOS"
RES="$CONTENTS/Resources"
MODEL_SRC="$SRC/Resources/Model.xcdatamodeld/Model.xcdatamodel/contents"
PLIST_SRC="$SRC/Resources/Info.plist"

echo "==> Checking toolchain"
if ! command -v xcrun >/dev/null 2>&1; then
  echo "xcrun not found. Run: xcode-select --install" >&2
  exit 1
fi
SDK="$(xcrun --show-sdk-path --sdk macosx 2>/dev/null || true)"
SWIFTC="$(xcrun -f swiftc 2>/dev/null || true)"
PLUTIL="$(command -v plutil || true)"
CODESIGN="$(command -v codesign || true)"
if [ -z "$SDK" ] || [ -z "$SWIFTC" ] || [ -z "$PLUTIL" ] || [ -z "$CODESIGN" ]; then
  echo "Cannot locate macOS SDK / swiftc / plutil / codesign." >&2
  echo "Install Command Line Tools: xcode-select --install" >&2
  exit 1
fi

# ARCH=arm64|x86_64 overrides the host architecture (used by CI to build a
# universal binary from a single runner); defaults to the host arch.
ARCH="${ARCH:-$(uname -m)}"
case "$ARCH" in
  arm64)  TARGET="arm64-apple-macosx13.0" ;;
  x86_64) TARGET="x86_64-apple-macosx13.0" ;;
  *)
    echo "Unsupported architecture: $ARCH" >&2
    exit 1
    ;;
esac
echo "    SDK    : $SDK"
echo "    swiftc : $SWIFTC"
echo "    target : $TARGET"

echo "==> Assembling .app bundle"
rm -rf "$BUILD"
mkdir -p "$MACOS" "$RES"
cp "$PLIST_SRC" "$CONTENTS/Info.plist"

# Xcode build settings are literal strings in the checked-in Info.plist;
# replace them with real values so LaunchServices/TCC see a valid bundle.
"$PLUTIL" -replace CFBundleExecutable    -string "$APP_NAME"  "$CONTENTS/Info.plist"
"$PLUTIL" -replace CFBundleIdentifier    -string "$BUNDLE_ID" "$CONTENTS/Info.plist"
"$PLUTIL" -replace CFBundleDisplayName   -string "划译"       "$CONTENTS/Info.plist"
"$PLUTIL" -lint "$CONTENTS/Info.plist" >/dev/null

echo "==> Compiling Core Data model -> Model.momd"
MOMC="$(xcrun -f momc 2>/dev/null || true)"
if [ -n "$MOMC" ] && [ -x "$MOMC" ]; then
  "$MOMC" "$SRC/Resources/Model.xcdatamodeld/Model.xcdatamodel" "$RES/Model.momd"
  echo "    compiled with momc"
else
  echo "    momc not available; generating Model.momd with embedded Swift helper"
  GEN="$BUILD/.modelgen"
  mkdir -p "$GEN"
  cat > "$GEN/make_model.swift" <<'SWIFT'
import Foundation
import CoreData

/// Compiles an .xcdatamodel/contents XML file into a loadable .momd bundle.
/// This is the Command Line Tools fallback for Apple's momc.
final class ModelParser: NSObject, XMLParserDelegate {
    private(set) var entities: [NSEntityDescription] = []
    private var currentEntity: NSEntityDescription?
    private var currentAttributes: [NSAttributeDescription] = []
    private let moduleName: String

    init(moduleName: String) {
        self.moduleName = moduleName
        super.init()
    }

    func parser(_ parser: XMLParser,
                didStartElement elementName: String,
                namespaceURI: String?,
                qualifiedName qName: String?,
                attributes attributeDict: [String: String] = [:]) {
        switch elementName {
        case "entity":
            let entity = NSEntityDescription()
            entity.name = attributeDict["name"] ?? "Entity"
            let declaredClass = attributeDict["representedClassName"] ?? entity.name ?? "Entity"
            // Swift classes in the main executable are registered as <module>.<class>.
            entity.managedObjectClassName = declaredClass.contains(".")
                ? declaredClass
                : "\(moduleName).\(declaredClass)"
            currentEntity = entity
            currentAttributes = []
        case "attribute":
            let attribute = NSAttributeDescription()
            attribute.name = attributeDict["name"] ?? "attribute"
            attribute.attributeType = Self.attributeType(for: attributeDict["attributeType"] ?? "String")
            attribute.isOptional = (attributeDict["optional"] as NSString?)?.boolValue ?? false
            if let raw = attributeDict["defaultStringValue"] {
                attribute.defaultValue = Self.defaultValue(from: raw, type: attribute.attributeType)
            }
            currentAttributes.append(attribute)
        default:
            break
        }
    }

    func parser(_ parser: XMLParser,
                didEndElement elementName: String,
                namespaceURI: String?,
                qualifiedName qName: String?) {
        guard elementName == "entity", let entity = currentEntity else { return }
        entity.properties = currentAttributes
        entities.append(entity)
        currentEntity = nil
        currentAttributes = []
    }

    private static func attributeType(for raw: String) -> NSAttributeType {
        switch raw {
        case "UUID":            return .UUIDAttributeType
        case "Date":            return .dateAttributeType
        case "String":          return .stringAttributeType
        case "Boolean":         return .booleanAttributeType
        case "Integer 16":      return .integer16AttributeType
        case "Integer 32":      return .integer32AttributeType
        case "Integer 64":      return .integer64AttributeType
        case "Decimal":         return .decimalAttributeType
        case "Double":          return .doubleAttributeType
        case "Float":           return .floatAttributeType
        case "Binary":          return .binaryDataAttributeType
        case "Transformable":   return .transformableAttributeType
        default:                return .undefinedAttributeType
        }
    }

    private static func defaultValue(from raw: String, type: NSAttributeType) -> Any? {
        switch type {
        case .booleanAttributeType:
            return raw == "YES" || raw == "true" || raw == "1"
        case .integer16AttributeType, .integer32AttributeType, .integer64AttributeType:
            return Int(raw) as NSNumber?
        case .doubleAttributeType:
            return Double(raw) as NSNumber?
        case .floatAttributeType:
            return Float(raw) as NSNumber?
        case .decimalAttributeType:
            return NSDecimalNumber(string: raw)
        default:
            return raw
        }
    }
}

let args = CommandLine.arguments
guard args.count >= 4 else {
    FileHandle.standardError.write(
        "usage: make_model <contents.xml> <output.momd> <module-name>\n".data(using: .utf8)!)
    exit(2)
}
let xmlURL = URL(fileURLWithPath: args[1])
let outDir = URL(fileURLWithPath: args[2], isDirectory: true)
let moduleName = args[3]
let modelName = outDir.deletingPathExtension().lastPathComponent

guard let xmlParser = XMLParser(contentsOf: xmlURL) else {
    FileHandle.standardError.write("cannot read \(xmlURL.path)\n".data(using: .utf8)!)
    exit(1)
}
let delegate = ModelParser(moduleName: moduleName)
xmlParser.delegate = delegate
guard xmlParser.parse(), !delegate.entities.isEmpty else {
    FileHandle.standardError.write(
        "failed to parse \(xmlURL.path) (parser error: \(String(describing: xmlParser.parserError)))\n"
            .data(using: .utf8)!)
    exit(1)
}

let model = NSManagedObjectModel()
model.entities = delegate.entities

try FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)
for item in try FileManager.default.contentsOfDirectory(at: outDir, includingPropertiesForKeys: nil) {
    try FileManager.default.removeItem(at: item)
}
let archive = try NSKeyedArchiver.archivedData(withRootObject: model, requiringSecureCoding: false)
try archive.write(to: outDir.appendingPathComponent("\(modelName).mom"))
print("generated \(outDir.path) with \(model.entities.count) entity/entities")
SWIFT

  # Build the helper for the HOST architecture, not $TARGET: it is executed
  # locally to generate the .momd, and a cross-compiled helper cannot run
  # natively (e.g. arm64 helper on an Intel host, or vice versa).
  HOST_ARCH="$(uname -m)"
  case "$HOST_ARCH" in
    arm64)  HOST_TARGET="arm64-apple-macosx13.0" ;;
    x86_64) HOST_TARGET="x86_64-apple-macosx13.0" ;;
    *)      HOST_TARGET="$TARGET" ;;
  esac
  "$SWIFTC" \
    -target "$HOST_TARGET" \
    -sdk "$SDK" \
    -swift-version 5 \
    -O \
    -framework Foundation \
    -framework CoreData \
    -o "$GEN/make_model" "$GEN/make_model.swift"
  "$GEN/make_model" "$MODEL_SRC" "$RES/Model.momd" "$APP_NAME"
fi

# Copy resource directory as-is. There are no named image assets in this project
# (only Contents.json), and menu bar icons come from NSImage system names.
if [ -d "$SRC/Resources/Assets.xcassets" ]; then
  cp -R "$SRC/Resources/Assets.xcassets" "$RES/Assets.xcassets"
fi

echo "==> Compiling Swift sources"
SOURCES=()
while IFS= read -r source_file; do
  SOURCES+=("$source_file")
done < <(find "$SRC" -name '*.swift' -type f | sort)
echo "    source files: ${#SOURCES[@]} (entry: main.swift top-level code)"
if [ "${#SOURCES[@]}" -eq 0 ]; then
  echo "No Swift sources found under $SRC" >&2
  exit 1
fi

# Do NOT add -parse-as-library: Sources/MacTranslator/App/main.swift is top-level code.
"$SWIFTC" \
  -target "$TARGET" \
  -sdk "$SDK" \
  -swift-version 5 \
  -O \
  -framework AppKit \
  -framework ApplicationServices \
  -framework Carbon \
  -framework Combine \
  -framework CoreData \
  -framework CoreGraphics \
  -framework CryptoKit \
  -framework Foundation \
  -framework ScreenCaptureKit \
  -framework Security \
  -framework SwiftUI \
  -framework Vision \
  -o "$MACOS/$APP_NAME" \
  "${SOURCES[@]}"

echo "==> Signing"
# SIGN=auto (default): reuse the trusted self-signed certificate when present,
# otherwise fall back to ad-hoc. A certificate-signed app keeps Accessibility /
# Screen Recording grants across rebuilds; ad-hoc needs re-authorization.
SIGN_MODE="${SIGN:-auto}"
CERT_ID="${MT_SIGN_IDENTITY:-}"
SIGN_KC="$HOME/Library/Keychains/vtsign.keychain-db"
if [ "$SIGN_MODE" = "auto" ]; then
  if [ -z "$CERT_ID" ] && security find-identity -v -p codesigning "$SIGN_KC" 2>/dev/null \
      | grep -q "view-timer Dev"; then
    CERT_ID="view-timer Dev"
  fi
  if [ -n "$CERT_ID" ]; then
    SIGN_MODE="cert"
  else
    SIGN_MODE="adhoc"
  fi
fi

if [ "$SIGN_MODE" = "cert" ]; then
  if [ -z "$CERT_ID" ]; then
    CERT_ID="view-timer Dev"
  fi
  KC_PASS="${MT_SIGNING_KC_PASS:-}"
  if [ -z "$KC_PASS" ] && [ -f "$HOME/.viewtimer-sign/keychain.pass" ]; then
    KC_PASS="$(tr -d '\r\n' < "$HOME/.viewtimer-sign/keychain.pass")"
  fi
  if [ -n "$KC_PASS" ]; then
    security unlock-keychain -p "$KC_PASS" "$SIGN_KC" >/dev/null 2>&1 || true
  else
    echo "    [warning] no signing keychain password configured; trying anyway"
  fi
  if codesign --force --deep --sign "$CERT_ID" --keychain "$SIGN_KC" "$APP" 2>/dev/null; then
    echo "    signed with certificate: $CERT_ID"
    echo "    [note] if permission toggles do not stick, trust the cert root in System keychain:"
    echo "           sudo security add-trusted-cert -d -r trustRoot -p codeSign \\"
    echo "             -k /Library/Keychains/System.keychain $HOME/.viewtimer-sign/cert.pem"
  else
    echo "    [warning] certificate signing failed; falling back to ad-hoc"
    codesign --force --deep --sign - "$APP"
    SIGN_MODE="adhoc"
  fi
else
  codesign --force --deep --sign - "$APP"
  echo "    signed ad-hoc (rebuild requires re-authorizing permissions)"
fi
"$CODESIGN" --verify --strict "$APP" 2>/dev/null || true

echo ""
echo "Build complete: $APP"
echo "Launch:        open \"$APP\""
echo "Install:       ./scripts/install.sh"
echo ""
echo "First run: System Settings > Privacy & Security > Accessibility / Screen Recording,"
echo "           add $APP (use '-' then '+' again after an ad-hoc rebuild)."
echo ""
